:root{--bg:#17121f;--card:#201830;--line:#3a2c52;--txt:#efe6f7;--dim:#a894bf;
        --farm:#7dffa2;--thin:#ffd24d;--skip:#8a8fa8;--hi:#ff9fd0}
  html,body{margin:0;background:var(--bg);color:var(--txt);font-family:'Segoe UI',system-ui,sans-serif}
  header{padding:18px 24px 8px}
  h1{margin:0;font-size:26px;letter-spacing:1px}
  h1 b{color:var(--hi)}
  .stats{display:flex;gap:18px;color:var(--dim);font-size:13px;margin-top:6px;flex-wrap:wrap}
  .stats b{color:var(--txt)}
  .bar{display:flex;gap:10px;padding:10px 24px;flex-wrap:wrap;align-items:center;position:sticky;top:0;background:var(--bg);z-index:5;border-bottom:1px solid var(--line)}
  input[type=search],select{background:var(--card);border:1px solid var(--line);color:var(--txt);border-radius:9px;padding:7px 12px;font-size:13px;outline:none}
  .chip{border:1px solid var(--line);border-radius:20px;padding:5px 13px;font-size:12px;cursor:pointer;user-select:none}
  .chip.on{background:var(--hi);color:#231019;border-color:var(--hi);font-weight:700}
  table{width:100%;border-collapse:collapse;font-size:13.5px}
  th{position:sticky;top:57px;background:#241a33;color:var(--dim);text-align:left;padding:9px 12px;cursor:pointer;border-bottom:1px solid var(--line);font-size:12px}
  td{padding:9px 12px;border-bottom:1px solid #2a2038}
  tr.r:hover{background:#281e3c;cursor:pointer}
  .v{padding:2px 10px;border-radius:14px;font-weight:800;font-size:11px}
  .v.FARM{background:#173b2b;color:var(--farm)}
  .v.THIN{background:#3b3117;color:var(--thin)}
  .v.SKIP{background:#2a2c38;color:var(--skip)}
  .c{color:var(--dim);font-size:12px}
  .bdg{display:inline-block;background:#2b2140;border-radius:10px;padding:1px 8px;margin-right:3px;font-size:11px;color:#cbb7dd}
  .imp{color:#7dffa2;font-weight:800}
  .conf{font-size:10px;letter-spacing:1px;padding:1px 7px;border-radius:8px}
  .conf.HIGH{background:#173b2b;color:#7dffa2}.conf.MEDIUM{background:#3b3117;color:#ffd24d}.conf.LOW{background:#2a2c38;color:#8a8fa8}
  #detail{position:fixed;right:0;top:0;bottom:0;width:min(560px,92vw);background:#241a33;border-left:1px solid var(--line);padding:22px;overflow-y:auto;display:none;box-shadow:-12px 0 40px #0008;z-index:9}
  #detail h2{margin:4px 0 2px}
  #detail .close{float:right;cursor:pointer;color:var(--dim);font-size:22px}
  .kv{display:grid;grid-template-columns:150px 1fr;gap:5px 12px;font-size:13.5px;margin:12px 0}
  .kv b{color:var(--dim);font-weight:600}
  .factor{display:flex;justify-content:space-between;background:#1c1428;border-radius:9px;padding:7px 12px;margin:4px 0;font-size:13px}
  .factor b{color:#7dffa2}
